pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // typical future items are "dead space". Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits (waste almost nothing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // If this bin can still fit the next item after placement, bonus
    // (keeps bins usable for the lookahead stream).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Placement strands the lookahead item: penalize proportionally.
        score += (next_item_size as f64) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (applied to the empty-bin candidate, which has bin_residual == capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a decent existing fit.
        score += 15.0;
        // But when few bins are open or the item is large, opening fresh is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (open_bins_count as f64) * 2.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If mean residual across open bins is small, new bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    } else {
        // Existing bin: mild preference for bins tighter than average
        // (best-fit bias), scaled by open-bin pressure.
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual is "dead" if it is too small to hold the smallest plausible item (1..100 range).
    let dead_threshold = 10.0f64; // conservative small-gap threshold
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward leaving that space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // stranded space relative to known next item
    }

    // New-bin candidate handling: allow opening a new bin only when all open bins
    // would produce bad (dead-space) fits.
    if bin_residual == bin_capacity {
        // neutral-ish base; slightly above a perfect fit on an open bin
        score = (bin_capacity as f64) * 0.9;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin is attractive if next item is large and current fit would be terrible
            if post_residual < dead_threshold {
                score -= 20.0;
            }
        }
    }

    // Progression: later in the stream, be more conservative about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frac = pr / cap;

    // base: compact residual preference with non-linear shaping (from donor direction)
    let mut score = frac * 100.0 + frac * frac * 70.0;

    // dead-space penalty for tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 12.0;
    }
    if post_residual == 0 { score -= 56.0; }

    // divisibility shaping of residual space (best-heuristic idea)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 15.0; }
        else if post_residual % 5 == 0 { score -= 9.0; }
        else if post_residual % 3 == 0 { score += 1.5; }
        else if post_residual % 2 == 0 { score += 5.5; }
        else { score += 13.5; }
    }

    // next-item lookahead: gaussian fit coupling
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_gap = (frac - nx).abs();
        score -= 7.5 * (-8.0 * fit_gap * fit_gap).exp();
        if next_item_size == post_residual { score -= 58.0; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 23.0 - slack * 0.4;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 9.5 + gap * 0.22;
        }
        if next_item_size as f64 > mean_residual * 0.75 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // tightness of the actual placement
    if item_size > 0 {
        let tightness = (bin_residual as f64 - item_size as f64) / cap;
        score += tightness * 8.0;
        if fitting_bins_count > 3 {
            score -= 2.0 * (-12.0 * tightness * tightness).exp();
        }
    }

    // unique-fit preference
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 25.0; }

    // open-bin count pressure
    score += (open_bins_count as f64) * 1.5;

    // new-bin candidate handling
    if bin_residual == bin_capacity {
        let frag = (open_bins_count as f64 / total_items.max(1) as f64).min(0.5);
        score = cap * 0.9 + 6.0 + 12.0 * (1.0 - progress) + 10.0 * frag;
        if fitting_bins_count == 0 { score -= 100.0; }
        if post_residual > 0 && post_residual < 8 { score -= 3.0; }
    }

    // mild progress coupling
    score += progress * pr * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // A residual is "unusable" if smaller than the minimum plausible item size.
        let min_item = 1.0f64;
        if (post_residual as f64) <= min_item * 10.0 {
            score += 60.0; // dead space penalty
        }
        // Non-linear coupling: small gaps that can't fit the lookahead item are worse.
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 12.0 + 0.5 * (post_residual as f64);
        } else if next_item_size > 0 {
            // Reward bins whose leftover can host the next item.
            score -= 8.0;
        }
        // Perfect fit reward.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> allow.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual close to item (avoid wasting large bins on small items).
    score += 0.15 * ((bin_residual as f64) - (item_size as f64)).abs();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by mean residual of open bins.
        score = 45.0 + 0.4 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is large, a fresh bin is more flexible.
            score -= 10.0;
        }
    }

    score
}

