pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let x = pr / cap ;
    // base: post-residual with convex coupling (borrowed from best)
    let mut score = post_residual as f64 * (1.0 + 0.9 * x * x) * 0.95 + x * 0.05 ;
    // dead-space shaping: penalize stranded awkward gaps
    let dead = (cap - item_size as f64 - pr) / cap ;
    if dead > 0.0 && dead < 0.06 { score += 3.0 * dead / 0.06 ; }
    else if dead >= 0.06 && dead < 0.14 { score += 1.0 * (dead - 0.06) / 0.08 ; }
    else if dead >= 0.14 && dead < 0.30 { score -= 0.7 * (dead - 0.14) / 0.16 ; }
    // near-zero residuals strongly rewarded
    if post_residual == 0 { score -= 500.0 ; }
    else {
        if post_residual < 10 { score += (10 - post_residual) as f64 * 40.0 ; }
        else if post_residual < 20 { score += (20 - post_residual) as f64 * 8.0 ; }
        else if post_residual % 5 == 0 { score -= 6.0 ; }
        else if post_residual % 2 == 0 { score += 3.5 ; }
        else { score += 8.0 ; }
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 60.0 ; }
    let pressure = (open_bins_count as f64) . ln () . max (0.0) ;
    score += pressure * 5.0 ;
    // new-bin candidate
    if bin_residual == bin_capacity {
        score += 80.0 + item_size as f64 * 0.2 ;
        let frag = open_bins_count as f64 / total_items . max (1) as f64 ;
        score += 6.0 * (1.0 - progress) + 10.0 * frag . min (0.5) ;
        if item_size as f64 >= cap * 0.55 { score -= 7.0 ; }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && progress < 0.5 && open_bins_count > 3 { score -= 2.5 ; }
        let stranded = item_size as f64 > mean_residual * 1.6 && fitting_bins_count <= 1 ;
        if stranded && progress > 0.15 { score -= 12.0 * (1.0 - progress) ; }
    }
    // lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 120.0 ; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 60.0 - slack * 0.4 ;
            let room2 = post_residual . saturating_sub (next_item_size) as f64 ;
            if room2 > 0.0 && room2 <= mean_residual * 0.35 { score -= 3.0 ; }
            if room2 > 0.0 && (room2 / cap) < 0.02 { score -= 4.0 ; }
        } else {
            let near_miss = next_item_size as i64 - post_residual as i64 ;
            if near_miss <= 4 { score += 2.5 + 0.5 * near_miss as f64 ; }
            else { score += 6.0 + (next_item_size - post_residual) as f64 * 0.15 ; }
        }
        if next_item_size as f64 > mean_residual * 0.75 && post_residual >= next_item_size { score -= 8.0 ; }
        if next_item_size + item_size == bin_residual { score -= 10.0 ; }
        if post_residual > 0 && post_residual * 2 == next_item_size { score -= 3.0 ; }
    }
    score += (mean_residual - bin_residual as f64) * 0.3 ;
    // tight fit bonus
    let tight_frac = item_size as f64 / bin_residual . max (1) as f64 ;
    if tight_frac > 0.9 && bin_residual != bin_capacity { score -= 5.0 * tight_frac ; }
    if tight_frac > 0.98 { score -= 4.0 ; }
    // progress coupling amplifies good fits late in stream
    let prog_coupling = 1.0 + 2.5 * progress * progress ;
    score *= prog_coupling ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post_residual (tight fit), polynomially amplified over time.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Smooth non-linear interaction: tight fits matter more late in the stream,
    // wasted space matters more when many bins are open.
    let open_factor = (open_bins_count as f64).ln().max(0.0) + 1.0;
    score += open_factor * post_norm * post_norm * cap * (0.3 + 0.7 * progress);

    // Reward filling bins nearly completely with a smooth saturating term.
    let fill = 1.0 - post_norm;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Penalize leaving dead space that cannot fit the next item (smooth quadratic).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - post).max(0.0) / cap;
        score += 20.0 * gap * gap * cap;
        // Bonus if next item fits exactly in post_residual (smooth coupling).
        let fit_gap = (nxt - post).abs() / cap;
        score -= 6.0 * (1.0 - fit_gap.min(1.0)) * (1.0 - fit_gap.min(1.0));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight penalty for deviating from mean residual (balance bins smoothly).
    let dev = (post - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * cap;

    // New-bin candidate: make it attractive only when item is large or fits poorly elsewhere.
    if bin_residual == bin_capacity {
