    // Residuals in "small slivers" (0..=10) are near-perfect fills: strong reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 220.0;
    } else if pr <= 20 {
        score -= 60.0;
    } else {
        // Dead-space classing: integer division thresholds
        let class = pr / 25; // 0..3 harmonic band
        score += match class {
            1 => 25.0,   // 25..49: moderately wasted
            2 => 45.0,   // 50..74: half-bin waste, bad
            _ => 70.0,   // 75..99: large unusable remainder
        };
    }

    // Harmonic compatibility: does next item fit into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt as u32) <= pr {
            // Reward when the next item also fits snugly (post2 small)
            let post2 = pr - next_item_size;
            score -= 30.0 + (10.0 - (post2 % 11) as f64) * 2.0;
        } else {
            // Penalize residuals that no plausible next item can use
            let gap = nxt - pr as f64;
            if gap > 0.0 && gap <= 15.0 {
                score += 35.0; // near-miss: likely dead space
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Prefer filling bins with small residuals relative to the mean (balance avoidance)
    score -= (bin_residual as f64 - mean_residual) * 0.4;

    // Early stream: keep bins open (penalize new-bin creation mildly late, reward consolidation early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bin would leave huge dead space
        let waste_now = post_residual as f64;
        score += 80.0 - progress * 30.0;
        if waste_now > 70.0 {
            score += 20.0; // opening new bin to preserve big residual is fine
        }
    }

    // Modulo tie-breaker: prefer residuals that are "harmonic" multiples of 10
    score += (pr % 10) as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it would fit in the residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !new_bin {
        score -= 30.0;
    }

    // Mild preference for bins tighter than the mean residual (consolidating space).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slightly tighten standards as the stream progresses.
    score *= 1.0 + 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual), scaled non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    if next_item_size > 0 {
        // Perfect 2-step match: bin becomes exactly reusable by next item.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward proportionally to how well it fills.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= next_fill * 25.0;
        } else {
            // Next item won't fit here: penalize dead space relative to lookahead.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: bins tighter than average are precious, use them well.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        // This bin is tighter than average: penalize wasting it unless perfect fit.
        score += dev * 0.3;
    } else {
        score += dev * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New empty bin candidate: penalize unless current bins are nearly unusable.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).ln().max(1.0);
        score += 30.0 + crowded * 5.0;
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 40.0; // fresh bin perfect for the lookahead chain
        }
        if mean_residual < item_size as f64 {
            score -= 45.0; // no open bin can meaningfully hold items
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches zero.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space relative to the smallest plausible future item.
    if post_residual > 0 {
        score += 0.35 * (post_residual as f64).sqrt();
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if next item fills the bin almost completely after this placement.
        let chain_residual = post_residual - next_item_size;
        if chain_residual <= 10 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Dead space that the lookahead item cannot use: mild penalty.
        score += 2.5;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // Many open bins: prefer reusing existing bins over opening more.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    if bin_residual < bin_capacity {
        score -= 3.0 * crowding.min(4.0);
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fit elsewhere) or early in the stream with plenty of future demand.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let early = 1.0 - (step_index as f64 / total_items.max(1) as f64).min(1.0);
        score -= 4.0 * large_item + 3.0 * early;
        // Penalize opening a new bin when decent alternatives exist.
        score += 0.8 * (fitting_bins_count as f64).min(5.0);
    }

    // Global residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin fleet homogeneous and flexible).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
