    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), with cubic penalty
    let mut score = x * (1.0 + 2.0 * x * x);

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate larger residuals; late, punish them harder.
    let prog_coupling = 1.0 + 3.0 * progress * progress;
    score *= prog_coupling;

    // Smooth interaction: residual vs mean residual divergence
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev * cap * 0.01;

