        if nx > x {
            score += 4.0 * (nx - x);
        }
    }

    // Mild penalty for proliferating open bins, scaled smoothly by progress
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a fresh bin unless residual is large
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with a convex penalty on
    // mid-range dead space so tiny leftovers are tolerated but half-full bins are not.
    let pr = post_residual as f64;
    let frac = pr / cap;
    score = frac * 100.0 + (frac * frac) * 60.0;

    // Harmonic class of post_residual: bins whose leftover belongs to "useful"
    // residue classes (multiples of small divisors) are easier to fill later.
    let class_penalty = if post_residual == 0 {
        -40.0 // perfect closure, best possible
    } else if post_residual <= 10 {
        -18.0 // small residue, easy to plug
    } else if post_residual % 10 == 0 {
        -12.0 // decade-aligned leftover
    } else if post_residual % 5 == 0 {
        -6.0
    } else if post_residual % 3 == 0 {
        2.0
    } else if post_residual % 2 == 0 {
        5.0
    } else {
        12.0 // odd prime-ish dead space is hardest to reuse
    };
    score += class_penalty;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly reward; if next item cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack * 0.25; // exact-ish follow-up fits are golden
        } else {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are crowded
    // or the item is large; otherwise penalize opening fresh capacity.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 > 0.6 * cap;
        let mut nb = 30.0;
        if big_item { nb -= 12.0; }
        if crowding < 0.25 { nb -= 15.0; } // existing bins nearly full -> new bin ok
        if progress > 0.8 { nb += 5.0; }
        score += nb;
    }

    // Mild pressure toward consolidating into bins below mean fill.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual is "dead" if it is too small to hold the smallest plausible item (1..100 range).
    let dead_threshold = 10.0f64; // conservative small-gap threshold
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is good
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward leaving that space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // stranded space relative to known next item
    }

    // New-bin candidate handling: allow opening a new bin only when all open bins
    // would produce bad (dead-space) fits.
    if bin_residual == bin_capacity {
        // neutral-ish base; slightly above a perfect fit on an open bin
        score = (bin_capacity as f64) * 0.9;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin is attractive if next item is large and current fit would be terrible
            if post_residual < dead_threshold {
                score -= 20.0;
            }
        }
    }

    // Progression: later in the stream, be more conservative about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
