    // Mild penalty when bin deviates from mean residual (balance pressure)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    // New-bin candidate: slight penalty early, relaxes as stream progresses
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
