        if perfect_pair { score -= 10.0 ; }
        let leftover_pair = post_residual . saturating_sub (next_item_size) ;
        if leftover_pair > 0 && leftover_pair as f64 <= cap * 0.03 { score -= 7.0 ; }
        let room_after_next = post_residual . saturating_sub (next_item_size) ;
        if room_after_next > 0 && room_after_next as f64 <= mean_residual * 0.35 { score -= 3.0 ; }
        if room_after_next > 0 && (room_after_next as f64 / cap) < 0.02 { score -= 4.0 ; }
