    let dead = (cap - item_size as f64 - pr) / cap ;
    if dead > 0.0 && dead < 0.06 { score += 3.0 * dead / 0.06 ; }
    else if dead >= 0.06 && dead < 0.14 { score += 1.0 * (dead - 0.06) / 0.08 ; }
    else if dead >= 0.14 && dead < 0.30 { score -= 0.7 * (dead - 0.14) / 0.16 ; }
    // near-zero residuals strongly rewarded
    if post_residual == 0 { score -= 56.0 ; }
    else if post_residual <= 5 { score -= 27.0 ; }
    else if post_residual % 10 == 0 { score -= 15.0 ; }
    else if post_residual % 5 == 0 { score -= 9.0 ; }
    else if post_residual % 3 == 0 { score += 1.5 ; }
    else if post_residual % 2 == 0 { score += 5.5 ; }
    else { score += 13.5 ; }
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 60.0 ; }
    let pressure = (open_bins_count as f64) . ln () . max (0.0) ;
    score += pressure * 5.0 ;
    // new-bin candidate
    if bin_residual == bin_capacity {
        score += 80.0 + item_size as f64 * 0.2 ;
        let frag = open_bins_count as f64 / total_items . max (1) as f64 ;
        score += 6.0 * (1.0 - progress) + 10.0 * frag . min (0.5) ;
        if item_size as f64 >= cap * 0.55 { score -= 7.0 ; }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && progress < 0.5 && open_bins_count > 3 { score -= 2.5 ; }
        let stranded = item_size as f64 > mean_residual * 1.6 && fitting_bins_count <= 1 ;
        if stranded && progress > 0.15 { score -= 12.0 * (1.0 - progress) ; }
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 { score += 3.0 ; }
        if fitting_bins_count <= 1 { score += 2.0 ; }
    }
    // lookahead on next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap ;
        let fit_gap = (x - nx) . abs () ;
        score -= 7.5 * (- 8.0 * fit_gap * fit_gap) . exp () ;
        if nx > x { score += 4.5 * (nx - x) ; }
        if next_item_size == post_residual { score -= 120.0 ; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 23.0 - slack * 0.4 ;
            let room2 = post_residual . saturating_sub (next_item_size) as f64 ;
            if room2 > 0.0 && room2 <= mean_residual * 0.35 { score -= 3.0 ; }
            if room2 > 0.0 && (room2 / cap) < 0.02 { score -= 4.0 ; }
            if room2 > 0.0 && room2 < item_size as f64 && fitting_bins_count <= 2 { score -= 5.0 * (1.0 - progress) ; }
        } else {
            let near_miss = next_item_size as i64 - post_residual as i64 ;
            if near_miss <= 4 { score += 2.5 + 0.5 * near_miss as f64 ; }
            else { score += 9.5 + (next_item_size - post_residual) as f64 * 0.22 ; }
            if pr > 12.0 && pr < 25.0 { score += 3.0 * (1.0 - progress) ; }
        }
        if next_item_size as f64 > mean_residual * 0.75 && post_residual >= next_item_size { score -= 8.0 ; }
        if next_item_size + item_size == bin_residual { score -= 10.0 ; }
        if post_residual > 0 && post_residual * 2 == next_item_size { score -= 3.0 ; }
        if post_residual > 0 && post_residual == 2 * next_item_size { score -= 5.0 ; }
        let room3 = post_residual . saturating_sub (next_item_size) ;
        if room3 > 0 && next_item_size as f64 >= mean_residual * 1.2 {
            let r3 = room3 as f64 ;
            if r3 <= 10.0 { score -= 6.0 ; }
            else if r3 <= mean_residual * 0.5 { score -= 3.0 ; }
        }
        let leftover_pair = post_residual . saturating_sub (next_item_size) ;
        if leftover_pair > 0 && (leftover_pair as f64) <= cap * 0.03 { score -= 7.0 ; }
        if leftover_pair > 0 && (leftover_pair as f64) >= mean_residual * 0.9 { score -= 2.5 * (1.0 - progress) ; }
    }
