    }
    if post_residual as f64 / cap < 0.03 && post_residual > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - progress) ;
    }
    // progress coupling amplifies good fits late in stream
    let prog_coupling = 1.0 + 3.0 * progress * progress ;
    score *= prog_coupling ;
    score
