        if near_miss > 0 && near_miss <= 4 { score += 2.5 + 0.5 * near_miss as f64 ; }
        if next_item_size > 0 && post_residual == 2 * next_item_size { score -= 5.0 ; }
        if room_after_next >= next_item_size && next_item_size > 0 { score -= 3.5 ; }
