    // Reward tight fits (small waste relative to capacity).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Perfect fill is golden.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which costs ~one full capacity unit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large and no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of a fresh bin: its full residual (already 100) plus a tax.
        score += 30.0;
        // Large items justify opening a fresh bin.
        if item_size > 60 {
            score -= 25.0;
        }
        // If few bins fit the item and existing residuals are small, a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // Late in the stream, avoid leaving many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Lookahead: if the next item could use the leftover, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If the next item would strand in the leftover, penalize near-miss gaps.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter than average).
    score += 0.05 * (mean_residual - bin_residual as f64).abs().signum()
        * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
