pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward when the next item exactly matches
    // the post_residual (chained perfect fit).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += lookahead_gap * 0.8;

        // Exact chain: post_residual equals next item size -> subtract big bonus.
        if post_residual == next_item_size {
            score -= 400.0;
        }

        // If next item cannot fit anywhere else well, but fits here after this
        // placement, reward this bin.
        if next_item_size <= post_residual {
            score -= 60.0;
        } else {
            // Next item would be blocked by this placement: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: bins with residual below mean are "tighter"
    // than average; filling them further is good if it avoids dead space.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.3;
    } else {
        score += (resid_f - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline penalty for opening a new bin; overcome only by large items
        // or when existing bins would leave bad dead space.
        score += 150.0;
        // Large items are better placed in fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 120.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild preference for bins with larger residual among equal fits
    // (keeps small bins for small items) — but only when item is small.
    if item_size <= bin_capacity / 4 {
        score -= bin_residual as f64 * 0.1;
    }

    // Penalize creating tiny unusable dead space (1..=5 units).
    if post_residual > 0 && post_residual <= 5 {
        score += 80.0;
    }

    // Penalize very large leftover waste relative to capacity.
    score += (resid_f / bin_capacity as f64) * 20.0;

    // Slight scaling with number of open bins: discourage spreading when many
    // bins are already open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
