    else if post_residual % 10 == 0 { score -= 15.0 ; }
    else if post_residual % 5 == 0 { score -= 9.0 ; }
    else if post_residual % 3 == 0 { score += 1.5 ; }
    else if post_residual % 2 == 0 { score += 5.5 ; }
