        let room2 = post_residual . saturating_sub (next_item_size) as f64 ;
        if room2 > 0.0 && room2 <= mean_residual { score -= 4.0 ; }
        let near_miss = next_item_size as i64 - post_residual as i64 ;
        if near_miss > 0 && near_miss <= 4 { score += 2.5 + 0.5 * near_miss as f64 ; }
        if post_residual > 0 && post_residual <= 10 && next_item_size > post_residual { score += 2.0 ; }
        if room2 > 0 && room2 as f64 <= cap * 0.03 { score -= 7.0 ; }
        if room2 > 0 && room2 < item_size && fitting_bins_count <= 2 { score -= 5.0 * (1.0 - progress) ; }
    }
    // tightness reward
    let tight_frac = item_size as f64 / bin_residual . max (1) as f64 ;
    if tight_frac > 0.9 && bin_residual != bin_capacity { score -= 5.0 * tight_frac ; }
    if tight_frac > 0.98 { score -= 4.0 ; }
    // unique-fitting-bin preference (parent's grafted fragment, refined)
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 25.0 * (1.0 - 0.5 * progress) ; }
    // waste / fragility guards
    let mr = mean_residual . max (1.0) ;
    if bin_residual != bin_capacity {
        let waste = pr / (pr + item_size as f64) ;
        if waste > 0.55 && next_item_size as f64 > pr { score += 3.5 * (waste - 0.55) * (1.0 + progress) ; }
        if x > 0.30 && fitting_bins_count <= 2 && next_item_size as f64 > pr { score += 2.5 * (x - 0.30) ; }
        if pr > 0.0 && pr < item_size as f64 * 0.5 && next_item_size as f64 >= pr { score += 1.2 * (1.0 - progress) ; }
        if fitting_bins_count > 3 {
            if x > 0.0 && x < 0.04 && next_item_size as u32 > post_residual { score += 5.0 * (1.0 - progress) ; }
        }
    }
    // NEW-BIN candidate logic
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress ;
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 { score += 3.0 ; }
        if fitting_bins_count <= 1 { score += 2.0 ; }
        if next_item_size > 0 && next_item_size as f64 >= mean_residual * 1.1 && fitting_bins_count > 0 && post_residual > 0 && post_residual < next_item_size { score -= 2.4 * (1.0 - progress) ; }
        if progress > 0.75 && next_item_size as f64 > mean_residual { score += 1.2 ; }
        if fitting_bins_count > 0 && post_residual > 0 {
            let best_slack = post_residual . saturating_sub (next_item_size) as f64 ;
            if next_item_size > 0 && best_slack > 0.0 && best_slack < item_size as f64 * 0.35 { score -= 1.2 * (1.0 - progress) ; }
        }
        if item_size as f64 > mr * 1.6 && fitting_bins_count > 0 { score += 1.5 * progress ; }
        if next_item_size as f64 >= item_size as f64 && next_item_size as f64 <= mean_residual * 0.9 && fitting_bins_count == 0 { score -= 2.0 ; }
    }
    if bin_residual != bin_capacity && post_residual > 0 && post_residual < item_size { score += 3.0 * (1.0 - progress) ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead-aware).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 12.0 * (nxt - post_residual as f64) / 100.0;
        } else {
            // Reward bins that can also host the next item.
            score -= 8.0 * (post_residual as f64 - nxt) / 100.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are already open but sparse.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_f = open_bins_count as f64;
        let waste = mean_residual - (bin_capacity as f64 - mean_residual).max(0.0);
        score += 20.0 + 0.3 * open_f + 15.0 * (1.0 - progress) + 0.1 * waste.max(0.0);
        // A new bin is acceptable only if the item is huge and nothing fits well.
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild penalty for leaving residuals that are hard to fill (small odd gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Reward filling bins that are below the mean residual (balancing pressure).
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 5.0 * (mean_residual - resid) / 100.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
