        if post_residual > 0 && post_residual < next_item_size && post_residual > 5 { score += 2.0 * (1.0 - progress) ; }
        if post_residual > mean_residual * 1.6 && post_residual < next_item_size { score += 4.0 * (1.0 - progress) ; }
    }
