pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: reward tight fits (low post_residual), with non-linear sharpening.
    let mut score = pr.powf(1.0 + 0.8 * progress);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space is penalized more aggressively.
    let coupling = fit_norm * fit_norm * (1.0 + 3.0 * progress) * cap;
    score += 0.5 * coupling;

    // Reward last-chance bins (avoid opening a new bin when only one fits).
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: favor bins whose post_residual could still fit the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0 + 2.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * progress;
    }

    // Mild penalty for spreading across many bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64) * (fit_norm - mean_residual / cap).abs();

    // Discourage opening a new bin when reasonable existing fits exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 10.0 * (1.0 - fit_norm.abs() ) * 0.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual (harmonic classes of C/8).
    let class = post_residual / (bin_capacity / 8); // 0..=8
    match class {
        0 => score -= 30.0,          // near-perfect fit: tiny dead space, excellent
        1 => score -= 18.0,          // leaves ~1/8..2/8: still usable for small items
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score += 3.0,           // exactly half-full: mildly awkward zone
        5 => score += 0.0,
        6 => score -= 2.0,
        7 => score -= 6.0,           // nearly empty bin: lots of flexibility
        _ => score -= 8.0,           // untouched bin
    }

    // Modulo arithmetic: residuals divisible by common small-item sizes are valuable.
    for m in [10u32, 20, 25, 50] {
        if post_residual >= m && post_residual % m == 0 {
            score -= 6.0;
        }
    }
    // Penalize odd dead space that few item sizes can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            score -= 5.0;
            let after_next = post_residual - next_item_size;
            if after_next % 10 == 0 {
                score -= 4.0; // harmonic alignment after lookahead placement
            }
            if after_next < 10 {
                score += 8.0; // lookahead would create a sliver
            }
        } else {
            score += 7.0; // next item won't fit here
        }
    }

    // Capacity-fraction coupling with current item size.
    let ifrac = item_size as f64 / cap;
    if ifrac > 0.7 {
        score -= 8.0; // big items preferentially consume open bins
    } else if ifrac < 0.2 {
        score += 2.0; // don't waste a good residual on a tiny item
    }

    // Last-chance bonus: only this bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are congested or item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (mean_residual / cap).max(0.1);
        let pressure = ifrac * 0.6 + congestion.min(3.0) * 0.2 + progress * 0.2;
        score = 60.0 - pressure * 25.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // fresh bin can host the pair
        }
    }

    // Mild tie-break toward filling fuller bins first.
    score -= (1.0 - frac) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // typical future items are "dead space". Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits (waste almost nothing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // If this bin can still fit the next item after placement, bonus
    // (keeps bins usable for the lookahead stream).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Placement strands the lookahead item: penalize proportionally.
        score += (next_item_size as f64) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (applied to the empty-bin candidate, which has bin_residual == capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a decent existing fit.
        score += 15.0;
        // But when few bins are open or the item is large, opening fresh is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (open_bins_count as f64) * 2.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If mean residual across open bins is small, new bin is attractive.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    } else {
        // Existing bin: mild preference for bins tighter than average
        // (best-fit bias), scaled by open-bin pressure.
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap;

    // base: compaction preference with cubic shaping (borrowed from best)
    let mut score = x * (1.0 + 2.6 * x * x);
    score *= 1.0 + 3.6 * progress * progress;

    // dead-space shaping
    if x > 0.0 {
        if x < 0.05 { score -= 2.2 * (1.0 - x / 0.05); }
        else if x > 0.20 { score += 2.8 * (x - 0.20); }
    }

    if post_residual == 0 { score -= 56.0; }
    else if post_residual <= 5 { score -= 27.0; }
    else if post_residual % 10 == 0 { score -= 15.0; }
    else if post_residual % 5 == 0 { score -= 9.0; }
    else if post_residual % 3 == 0 { score += 1.5; }
    else if post_residual % 2 == 0 { score += 5.5; }
    else { score += 13.5; }

    // next-item lookahead
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_gap = (x - nx).abs();
        score -= 7.5 * (-8.0 * fit_gap * fit_gap).exp();
        if nx > x { score += 4.5 * (nx - x); }
        if next_item_size == post_residual { score -= 58.0; }
        else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 23.0 - slack * 0.4;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 9.5 + gap * 0.22;
        }
        if next_item_size as f64 > mean_residual * 0.75 && post_residual >= next_item_size { score -= 8.0; }

        let room = post_residual.saturating_sub(next_item_size);
        let rf = room as f64;
        if room > 0 {
            if rf <= mean_residual { score -= 4.0; }
            if rf <= 10.0 && next_item_size as f64 >= mean_residual * 1.2 { score -= 6.0; }
            if rf < item_size as f64 && fitting_bins_count <= 2 { score -= 5.0 * (1.0 - progress); }
            if rf as u32 == next_item_size { score -= 6.0; }
            if rf >= next_item_size as f64 { score -= 3.5; }
            if rf / cap < 0.02 { score -= 4.0; }
        }
        if post_residual < next_item_size && post_residual > 5 { score += 2.0 * (1.0 - progress); }
        let near_miss = next_item_size as i64 - post_residual as i64;
        if near_miss > 0 && near_miss <= 4 { score += 2.5 + 0.5 * near_miss as f64; }
        if post_residual > 0 && post_residual * 2 == next_item_size { score -= 3.0; }
        if post_residual == 2 * next_item_size { score -= 5.0; }
    }

    // tightness of placement
    let tight_frac = item_size as f64 / bin_residual.max(1) as f64;
    if tight_frac > 0.9 && bin_residual != bin_capacity { score -= 5.0 * tight_frac; }
    if tight_frac > 0.98 { score -= 4.0; }
    if fitting_bins_count > 3 {
        let t = (bin_residual as f64 - item_size as f64) / cap;
        score -= 2.0 * (-12.0 * t * t).exp();
    }

    // unique-fit preference
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 25.0; }

    // open-bin count pressure
    score += (open_bins_count as f64) * 1.5;

    // waste-driven penalty when next item cannot use residual
    let mr = mean_residual.max(1.0);
    if bin_residual != bin_capacity {
        let waste = pr / (pr + item_size as f64);
        if waste > 0.55 && next_item_size as f64 > pr {
            score += 3.5 * (waste - 0.55) * (1.0 + progress);
        }
        if x > 0.30 && fitting_bins_count <= 2 && next_item_size as f64 > pr {
            score += 2.5 * (x - 0.30);
        }
        if post_residual > 0 && post_residual < item_size { score += 3.0 * (1.0 - progress); }
        if fitting_bins_count > 3 {
            if x > 0.0 && x < 0.04 && next_item_size as u32 > post_residual {
                score += 5.0 * (1.0 - progress);
            }
        }
    }

    // new-bin candidate handling
    if bin_residual == bin_capacity {
        let frag = (open_bins_count as f64 / total_items.max(1) as f64).min(0.5);
        score = cap * 0.9 + 6.0 + 12.0 * (1.0 - progress) + 10.0 * frag;
        if fitting_bins_count == 0 { score -= 100.0; }
        if next_item_size as f64 > mr * 1.5 { score += 3.0; }
        if fitting_bins_count <= 1 { score += 2.0; }
        if progress > 0.75 && next_item_size as f64 > mr { score += 1.2; }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 2.4 * (1.0 - progress);
        }
    }

    score += progress * pr * 0.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strongly discourage opening a new bin unless
    // nothing reasonable exists (handled via fitting_bins_count).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 + 4.0 * fitting_bins_count as f64 };
        return 1000.0 + pressure;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual
    // with next_item_size (perfect chain), scaled by lookahead availability.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: strong reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if next_item_size > post_residual {
            // Next item cannot fit here afterwards: penalize dead space.
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits but imperfectly: mild penalty proportional to mismatch.
            score += 0.3 * diff;
            // Small bonus if post_residual stays usable for typical sizes (>= 10).
            if post_residual >= 10 {
                score -= 5.0;
            }
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good packing density).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow slightly looser packing to keep options open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: exact/near-exact fits are heavily favored.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin;
    // if it would be wasted on a too-large next item, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: only one bin can fit this item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Fragmentation pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let frag = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score += frag * (open_bins_count as f64).ln() * 2.0;
    }

    // Time horizon: early in the stream, be conservative (favor new bins for
    // large items to keep flexibility); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize normally, but less when item is large
        // or early in the stream, more when it would create tiny dead space.
        score += 15.0 - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
    } else {
        score -= 4.0 * progress;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual in [0, 1]
    let post_n = post / cap;

    // Smooth non-linear coupling: squared post-residual grows penalty
    // quadratically for large dead space, but scaled by stream progress
    // (late in the stream, tight fits matter more).
    let progress_sq = progress * progress;
    score += 20.0 * post_n * post_n * (0.5 + progress);

    // Reward near-perfect fits smoothly: cubic falloff of residual
    score -= 15.0 * (1.0 - post_n).powi(3);

    // Interaction with mean residual: penalize bins far from the mean
    // residual (encourages homogeneity of open bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bonus: smooth sigmoid-like boost when few bins fit
    let fitting = fitting_bins_count as f64;
    let last_chance = 1.0 / (1.0 + fitting * fitting);
    score -= 12.0 * last_chance;

    // Lookahead coupling: reward bins whose post-residual matches the
    // next item smoothly (Gaussian-like affinity).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        score -= 8.0 * (-diff * diff * 50.0).exp();
    }

    // Mild penalty for spreading across many open bins, weighted by progress
    score += 0.3 * (open_bins_count as f64) * progress_sq;

    // Small early-stream bonus for using fresh capacity (new-bin candidate
    // gets an advantage early, less so later).
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on a
    // "usable" residue class (divisible by common small item sizes) are
    // rewarded, since future items are more likely to fit exactly.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -8.0 // perfect fill: best possible outcome
    } else if pr % 10 == 0 {
        -3.0
    } else if pr % 5 == 0 {
        -1.5
    } else if pr >= 10 {
        0.0
    } else {
        4.0 // dead space below minimum item size: strongly penalize
    };
    score += class_bonus;

    // Integer-division threshold: leftover bucketed into quarters of capacity.
    let quarter = (pr * 4) as f64 / cap;
    if quarter < 0.25 {
        score += 3.0; // tiny leftover: wasteful
    } else if quarter > 1.75 {
        score -= 2.0; // large leftover: bin stays flexible
    }

    // Lookahead coupling: reward if the next item fits the post-residual
    // (exact or harmonic match), penalize near-misses.
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni <= pr {
            if pr % ni == 0 {
                score -= 4.0;
            } else if pr - ni < 10 {
                score += 2.0; // next item barely fits, leaves dead space
            } else {
                score -= 1.0;
            }
        } else {
            score += (ni - pr) as f64 * 0.25; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 2 {
        score += 1.0; // plenty of alternatives, be picky
    }

    // New empty bin candidate: must be chosen only when fits are terrible.
    if bin_residual == bin_capacity {
        // Base penalty grows with how many bins could already fit the item.
        score = cap * 0.6 + (fitting_bins_count as f64) * 4.0
            - (post_residual as f64) * 0.1;
        // Early in stream: slightly cheaper to open bins (builds a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        score -= (1.0 - progress) * 5.0;
        // If open bins are crowded on average, opening is more attractive.
        score -= (mean_residual - 30.0).max(0.0) * 0.05;
    }

    // Mild preference for tighter bins (low mean residual context).
    score += (mean_residual - bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
