pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold typical items are wasted.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // Hard penalty scaled by how "dead" the gap is.
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    // Mid-range gaps (hard to fill later) get a soft penalty.
    if post_residual >= dead_threshold && post_residual < 30 {
        score += 6.0;
    }

    // Reward perfect / tight fits.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= fit_ratio * 25.0;
    }

    // Last chance: this is the only bin that fits — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / 20.0;
        let poor_fit = if post_residual == 0 { 0.0 } else { 1.0 };
        score += 45.0 + crowding * 10.0 - progress * 10.0 - poor_fit * 0.0;
        // If no open bin fits well, opening a new bin is less penalized.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Lookahead: prefer bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Slight preference for bins below mean residual (fill emptier bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 40.0 - leftover * 1.5;
    }
    // Next item cannot follow in this bin: penalize proportionally to wasted chain opportunity.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.4;
    }

    // Reward tight fills relative to mean residual of open bins.
    let mean_r = mean_residual.max(0.0);
    if (post_residual as f64) < mean_r {
        score -= (mean_r - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_r) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Slight preference for keeping few bins open early; allow new bins later in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a perfect next-item chain.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
        score += (1.0 - progress) * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty for large post-residual
    let cap = bin_capacity as f64;
    let frac_post = post_residual as f64 / cap;
    score += 40.0 * frac_post * frac_post;

    // Exact / near-exact fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let fit_ratio = nxt / (post_residual as f64 + 1.0);
            score -= 12.0 * fit_ratio;
        } else {
            // next item cannot use leftover space: penalize dead space
            score += 6.0;
        }
    }

    // Prefer bins with residual above mean (keep tight bins tight-free)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in stream, be more conservative (favor filling existing bins);
    // late in stream, prefer tight packing aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * frac_post;

    // Many open bins: discourage spreading; few open bins: opening is cheaper
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * frac_post;

    // New-bin candidate: penalize slightly unless item is large relative to a fresh bin
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        score += 10.0 - 14.0 * size_ratio;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, but weighted by stream progress (late waste matters more)
    let mut score = pr * (0.7 + 0.6 * progress);

    // Smooth non-linear coupling: quadratic in normalized post residual, modulated by progress
    score += 18.0 * pr_norm * pr_norm * (1.0 + progress);

    // Dead-space penalty: post residual too small for typical future items (smooth sigmoid-ish via tanh)
    let dead = ((pr - 50.0) / 25.0).tanh();
    score += 6.0 * (1.0 - dead) * pr_norm;

    // Lookahead: reward if next item fits the post residual (smooth interaction)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64) / 20.0;
        score -= 10.0 / (1.0 + (-fits).exp()) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using a scarce fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild pressure to prefer existing bins over new ones as bins accumulate
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0) + 6.0 * progress;
    }

    // Smooth tie-break toward bins tighter than average
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual: quarters of capacity ----
    // Residuals in the lowest quarter are "dead space" (unusable for typical items).
    let q = (post_residual * 4) / bin_capacity; // 0..=4 integer class
    match q {
        0 => score -= 40.0,                 // near-perfect fit
        1 => score += 12.0,                 // small but awkward leftover
        2 => score += 0.0,                  // half-full: flexible
        3 => score -= 8.0,                  // large residual: still useful
        _ => {}                             // empty/new bin class
    }

    // ---- Modulo-style thresholds on post_residual ----
    // Residuals that cannot hold even the smallest plausible item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Harmonic "sweet spots": residuals divisible into common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // ---- Lookahead coupling: does next item fit in the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability is valuable, especially exact/near-exact chains
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 0.25 * slack;
        } else {
            // next item won't fit here: penalize proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.3 * over;
        }
    }

    // ---- Last-chance bonus: only fitting bin before opening a new one ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Prefer new bin only late in the stream or when few bins fit the item
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (fitting_bins_count as f64).recip();
        score -= 30.0 * progress * scarcity;
        // Penalize opening new bins when many bins are already open and loose
        score += 0.5 * open_bins_count as f64;
    }

    // ---- Mean residual drift: prefer bins below mean residual (tighter bins) ----
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Slight preference for larger items into tighter bins (big item, small residual)
    score -= 0.1 * item_size as f64 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
