    score += (mean_residual - bin_residual as f64) * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the fit is terrible or no
    // real bin fits well; keep a modest baseline penalty otherwise.
    if bin_residual == bin_capacity {
        score += 14.0 + post_residual as f64 * 0.2;
    }

    score
