pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect 2-item match
        } else if next_item_size <= post_residual {
            // partial fit: reward proportional to how much of post_residual is used
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * frac;
        } else {
            // next item cannot fit here: penalize large dead space relative to mean residual
            let dead = post_residual as f64;
            if dead < mean_residual {
                score += 0.5 * (mean_residual - dead);
            }
        }
    }

    // Penalize tight-dead-space: small post_residual that is unusable
    if post_residual < 10 {
        score += 15.0; // creates tiny unusable gap
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Discourage opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * mean_residual;
        // but if existing residuals are all poor fits (large waste), new bin is fine
        let waste = (post_residual as f64 - item_size as f64).abs();
        let _ = waste;
        if next_item_size > 0 && next_item_size > bin_residual - item_size && mean_residual < item_size as f64 {
            score -= 90.0;
        }
    }

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.2;

    // Prefer bins already below mean residual (consolidating space)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post residual to heavily penalize large dead space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + (item_size as f64) * 0.2;
    }

    // Lookahead coupling: if the next item can use this bin's post residual,
    // reward the placement; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item could chain into this bin: good if residual closely matches.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else if next_item_size > bin_residual {
            // Next item won't fit this bin anyway; placement cost is just post residual.
            score += 5.0;
        } else {
            // Next item fits current residual but we consumed space it needed: penalize.
            score += 12.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge post residual; make it
    // attractive only when existing bins fit poorly or are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit_elsewhere = if fitting_bins_count > 0 && (bin_residual - item_size) == 0 { 0.0 } else { 0.0 };
        let _ = poor_fit_elsewhere;
        // Base new-bin score: moderately high, but drops under congestion / no alternatives.
        score = 40.0 + post_residual as f64 * 0.3
            - 30.0 * pressure
            - congestion.min(25.0);
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If lookahead is small, a fresh bin can absorb it well.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    }

    // Global residual pressure: when open bins have lots of total slack, prefer
    // consolidating into them rather than leaving scattered residuals.
    score += 0.05 * mean_residual;

    // Mild time-decay on wasted residual: early waste is more forgivable than late waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), scaled by stream progress.
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth cubic coupling: tight fits rewarded more as stream advances.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * progress * tightness * tightness * tightness;

    // Penalize bins whose residual diverges from mean residual (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin, smoothly damped by progress.
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 4.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 2.0 * progress;
    }

    // Mild penalty for opening new bins late in the stream; encourage early spread.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

