    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward: strong discount for near-zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

