pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum plausible item are "dead" — penalize them extra hard.
    let min_item = 1.0f64;
    let usable = post_residual as f64 >= min_item;
    if !usable {
        score += 1000.0; // essentially never create a fully unusable gap
    } else {
        // Non-linear penalty: small-but-nonzero gaps are worse than large ones.
        let gap = post_residual as f64;
        score += 40.0 * (1.0 - gap / bin_capacity as f64).powi(6);
    }

    // Reward tight fits (item nearly fills the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing space
    // over spreading; a new-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if this is the only fitting bin, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let perfect_next = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 / (1.0 + perfect_next);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 5.0;
    }

    // Mean-residual coupling: keep residuals balanced across open bins.
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    // Late in the stream, be more conservative (favor consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

