    };

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    // Spread pressure: when many bins are open with high mean residual,
    // slightly discourage adding to fragmented space.
    let spread = (mean_residual / cap) * (open_bins_count as f64).ln_1p() * 4.0;

    base + dead + fit_reward + look + last_chance + spread
