pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // class (large enough for typical future items) are penalized less.
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic class 0..10
    match class {
        0 => score += 25.0,          // dead space <= 9: very bad
        1 => score += 12.0,          // 10..19 marginal
        2 => score -= 2.0,           // 20..29 usable
        3 => score -= 4.0,
        4 => score -= 5.0,
        5 => score -= 4.0,
        6 => score -= 2.0,
        7 => score += 6.0,           // 70..79 wasteful large leftover
        8 => score += 10.0,
        9 => score += 14.0,
        _ => {}                      // fresh bin (100)
    }

    // Integer-division harmonic classes on next_item_size vs post_residual:
    // perfect or near-perfect lookahead fit is heavily rewarded.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 30.0; // next item exactly fills this bin
        } else if slack <= 5 {
            score -= 18.0;
        } else if slack <= 15 {
            score -= 8.0;
        }
        // Harmonic divisibility: next item fits into leftover in halves/quarters
        if pr % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this bin's leftover: leftover value drops
        score += 8.0;
        if pr < 10 {
            score += 10.0; // guaranteed dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Fresh-bin candidate: prefer it only when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 10.0 * frac; // big items deserve fresh bins
        } else {
            score += 15.0; // discourage wasting fresh bins on small items
        }
    }

    // Progress coupling: late in the stream, tighten up (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (mean_residual / cap);

    // Prefer fuller bins overall: pull toward mean residual alignment.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hardest.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Medium gaps below the smallest plausible item are also dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: if the next item fits the post-residual gap, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item barely misses the created gap (fragmentation risk).
    if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, so post_residual is large;
    // add pressure proportional to open bins for such candidates).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 8.0;
        // Mild progress-based tolerance for new bins late in the stream.
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins with residual below the mean (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills this bin's post-residual (perfect 2-step match).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_quality = 1.0 / (1.0 + diff / 10.0);
        score -= 30.0 * match_quality;

