        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Penalize leaving dead space that is too small for the smallest plausible next item (1).
    if post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins with below-average residual (tighter bins) when item fits.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the item is large
    // and current bins are fragmented (high mean residual with poor fit).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let openness = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 20.0 * fragmentation - 10.0 * openness;

        // If lookahead can pair with a fresh bin (item + next item <= capacity),
        // opening a new bin becomes more attractive.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 25.0;
        }
    }

    // Mild progression bias: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

