        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size >= 60;
        if large_item && progress < 0.7 && open_bins_count > 0 {
            score -= 15.0; // fresh bin for big items early on
        } else {
            score += 40.0; // default: keep using open bins
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open the first bin
        }
    }

    // Coupling with mean residual: if this bin is far below the mean
    // residual, filling it tightens the residual distribution.
    let diff = mean_residual - post_residual as f64;
    if diff > 20.0 {
        score -= 10.0; // harmonize residuals toward the mean
    } else if diff < -20.0 {
        score += 10.0; // this bin is already tighter than average
    }

    score
