pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold the smallest item (1)
    // are pure waste; penalize small nonzero post_residuals heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Perfect fit rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item if it could
    // otherwise have been used.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over spreading; make new bins progressively less attractive.
    let open_pressure = open_bins_count as f64 * 3.0;
    if bin_residual == bin_capacity {
        score += open_pressure;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly prefer using it before opening another.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: if this bin is far below mean residual it is
    // relatively full; favor it.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late-stream tightness: as stream progresses, avoid waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 40.0 * f64::exp(-diff / 6.0);

        // Penalize if next item cannot fit into post_residual (dead space for next step)
        if next_item_size as u32 > post_residual {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit
        score += 20.0;
    }

    // Penalize very small unusable dead space (< 10) unless it's the last item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // A new bin is good if the item is large (fills it well)
        score = 60.0 + 40.0 * fit_quality - 30.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count > 0 {
            score += 20.0; // discourage opening new bin when alternatives exist
        }
    }

    // Mild tie-breaking against mean residual: prefer bins below-average residual
    // (tighter bins get slight priority), scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.1 * (mean_residual - post_residual as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - t);
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: prefer leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the ability to fit the next item here.
            score += 10.0 * (1.0 - fit_ratio);
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.6;
        let no_good_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && fit_ratio < 0.35 && post_residual > 0);
        if crowded || no_good_fit {
            score -= 20.0 + 15.0 * t;
        } else {
            score += 30.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Mild preference for filling bins in an already-large fleet.
    score += 0.05 * open_bins_count as f64;

    // Slight global pressure to use existing residual mass over time.
    score -= 0.02 * mean_residual * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post_residual (tight fit), with non-linear shaping
    let mut score = pr as f64;

    // Smooth non-linear interaction: tight fits rewarded more as stream progresses
    let tightness = (1.0 - x).powi(3);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize dead space (unusable residual) with cubic growth
    if let Some(nx) = next_item_size as f64 > 0.0 {
        let nx = next_item_size as f64;
        let unusable = ((nx - pr) / cap).max(0.0);
        score += 8.0 * unusable.powi(2) * (1.0 + progress);
        // Reward bins whose residual can hold the next item
        if pr >= nx {
            score -= 5.0 * (pr / cap) * (1.0 - progress);
        }
    } else {
        // End of stream: strongly prefer filling bins as tightly as possible
        score += 6.0 * x * x;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0 * (1.0 - x * x);
    }

    // Mild penalty when many bins are open and residual is wasteful
    score += 0.05 * (open_bins_count as f64) * x * (1.0 - progress);

    // Coupling with mean residual: prefer bins near the mean (balanced packing)
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: make it unattractive unless residual is essentially full capacity
    if bin_residual == bin_capacity {
        score += 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly: small post_residual is good.
    score -= 40.0 * (1.0 - (post_residual as f64) / bin_capacity as f64).powi(3);

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are more likely to be reusable later.
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fit, ideal
    } else if pr % 50 == 0 {
        score -= 30.0;
    } else if pr % 25 == 0 {
        score -= 20.0;
    } else if pr % 20 == 0 {
        score -= 18.0;
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else {
        // Awkward residue classes get penalized by their distance to a
        // "nice" multiple of 10.
        let r = pr % 10;
        score += 8.0 * (5 - r.abs_diff(0).min(10 - r)) as f64;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can follow in this bin: strong reward.
            let slack = pr - next_item_size;
            score -= 25.0 - 0.15 * slack as f64;
            if slack % 10 == 0 {
                score -= 10.0; // double harmonic fit
            }
        } else {
            // Next item cannot fit here: penalize, worse if we wasted space.
            score += 0.25 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when existing fits
    // are poor. Penalize the fresh bin, scaled by stream progression and how
    // many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if mean residual across open bins is tiny (all bins nearly full),
        // opening a new bin is fine: reduce the penalty.
        score -= (mean_residual * 0.4).min(60.0);
    }

    // Mild penalty for leaving very small dead space that nothing (min size 1..)
    // can use later, encouraging either exact fills or generous space.
    if pr > 0 && pr < 5 {
        score += 15.0;
    }

    score
}

