        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect chain fit (item exactly fills, or next item exactly fills remainder)
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual as u32 == next_item_size {
            score -= 45.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item could chain here: penalize proportional to leftover mismatch
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space that next item cannot use
            score += 15.0 + gap * 0.5;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 30.0;
    }

    // Tightness reward relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize bins whose residual deviates strongly from mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 25.0;
        // new bin more acceptable early in stream or when few bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for bins with smaller residual (best-fit flavor)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: heavily favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small post_residual that can't fit typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or global residuals are large (fragmentation is low anyway).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (fit_ratio < 0.55) as i32 as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size > bin_capacity / 2) as i32 as f64;
        score += 35.0; // base cost of opening a new bin
        score -= 45.0 * desperation;
        score -= 20.0 * poor_fit;
        score -= 10.0 * big_item;
        score -= 10.0 * progress; // later in stream, slightly more willing to open
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Prefer bins with residual close to item (best-fit flavor) among open bins.
        score += 0.05 * (bin_residual as f64 - item_size as f64).abs();
        // Mild preference for bins below mean residual (consolidate emptier space usage).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;

    // Dead-space penalty grows non-linearly (quartic) with small post-residual
    let dead = (1.0 - pr_norm).powi(4);
    score += 8.0 * dead * (0.5 + progress);

    // Reward tight fits: quadratic reward for small post_residual
    score -= 6.0 * (1.0 - pr_norm).powi(2) * (1.0 - progress);

    // Coupling term: post_residual * progress (later items prefer fuller bins)
    score += 2.0 * pr_norm * progress;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins: penalize spreading, encourage consolidation
    score += 0.5 * open_bins_count as f64 * pr_norm * (1.0 - progress);

    // Mean residual coupling: prefer bins deviating from the mean toward fullness
    score += 0.3 * (mean_residual - pr).abs();

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 5.0 * (1.0 - diff / bin_capacity as f64).powi(3);
    } else {
        // Last item: maximize fill, minimize post_residual aggressively
        score += 3.0 * pr_norm;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 5.0;
        // If item fits snugly in the new bin (large item), soften the penalty
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 12.0 * fill * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that align with common
    // item granularity (multiples of 10) are more reusable.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.8; // misaligned residues are slightly worse

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 10; // 0..=10 harmonic decade
    match class {
        0 => score -= 40.0,            // ultra-tight fit, excellent
        1 => score -= 25.0,            // very tight
        2 => score -= 12.0,            // tight
        3 => score -= 4.0,             // decent
        4 | 5 => score += 2.0,         // middling
        6 | 7 => score += 6.0,         // loose
        _ => score += 10.0,            // very loose
    }

    // Lookahead coupling: reward bins that can also host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // exact lookahead fit is gold
            if slack == 0 {
                score -= 60.0;
            } else {
                score -= 30.0 - (slack.min(30) as f64) * 0.3;
            }
        } else {
            // residual too small for the next item: dead-space penalty
            score += (next_item_size - post_residual) as f64 * 0.9;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation, penalize spreading further.
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 1.5;
    }

    // New empty bin candidate: make it unattractive by default; it wins only
    // when all open bins carry heavy penalties (poor fits).
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Slight pull toward bins near the mean residual (balance the fleet).
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // A residual is "unusable" if smaller than the minimum plausible item size.
        let min_item = 1.0f64;
        if (post_residual as f64) <= min_item * 10.0 {
            score += 60.0; // dead space penalty
        }
        // Non-linear coupling: small gaps that can't fit the lookahead item are worse.
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 12.0 + 0.5 * (post_residual as f64);
        } else if next_item_size > 0 {
            // Reward bins whose leftover can host the next item.
            score -= 8.0;
        }
        // Perfect fit reward.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> allow.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual close to item (avoid wasting large bins on small items).
    score += 0.15 * ((bin_residual as f64) - (item_size as f64)).abs();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by mean residual of open bins.
        score = 45.0 + 0.4 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is large, a fresh bin is more flexible.
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual).
    score = post_residual as f64 * 1.0;

    // Dead-space penalty: very small post_residual that can't fit typical items is fine,
    // but mid-range waste is bad. Penalize residuals in the awkward zone (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual (perfect chain).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 25.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how well it fills the remainder
            let fill_after = (post_residual as f64 - next) / bin_capacity as f64;
            score -= 12.0 * (1.0 - fill_after); // tighter secondary fit => bigger bonus
        } else {
            // next item won't fit here: penalize, worse if gap is small (near-miss waste)
            let gap = next_item_size as f64 - post_residual as f64;
            score += 4.0 + 0.15 * gap.min(30.0);
        }

        // Three-item chain potential: post_residual == item_size + next_item_size fits both
        if (item_size + next_item_size) == bin_residual {
            score -= 8.0;
        }
    } else {
        // Last item: any bin that fits is fine; strongly prefer tightest.
        score -= 5.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (consolidate fullness).
    score += 0.35 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if lookahead chains perfectly into a fresh bin, soften penalty.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 6.0;
        }
        // Early stream: allow more bins (spread risk); late stream: keep new-bin penalty high.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 6.0;
    }

    // Mild penalty for many open bins: encourage consolidation when bins are numerous.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared residual strongly favors near-perfect fits.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64 / post_residual as f64) * 8.0;
        } else {
            // Dead space for the next item: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64).min(50.0) * 0.6;
        }
    }

    // Time horizon: late in the stream, consolidate harder into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0;

    // Penalize bins that are already much emptier than average (fragmentation risk),
    // but only when many bins are open.
    if open_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when nothing fits well or the item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = post_residual; // = 0 for a fresh bin with this item
        let _ = best_possible;
        // Base penalty so open bins win when fit is decent.
        score += 25.0;
        // Reward opening a new bin when item is large (hard to place later).
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // When this item fits many bins, a new bin is wasteful.
        score += fitting_bins_count as f64 * 8.0;
        // If the next item is large too, a fresh bin with room may help pair them.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Small global pressure: more open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;
    // Non-linear coupling: residual value decays with progress (late residual worth less)
    score -= 8.0 * norm_pr * (1.0 - progress) * (1.0 + progress * progress);
    // Penalize unusable dead space (residual too small for typical future items)
    let deadness = if next_item_size > 0 {
        (1.0 - pr / next_item_size.max(1) as f64).max(0.0)
    } else {
        norm_pr
    };
    score += 6.0 * deadness * deadness * (0.5 + progress);
    // Reward tight fits (small post residual) with smooth quadratic term
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 * (1.0 + progress);
    }
    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.5 * ((open_bins_count as f64).ln() + 1.0) * (norm_pr - mean_residual / cap).abs();
    // Lookahead: favor bins whose post residual fits the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 3.0 * (pr - next_item_size as f64) / cap;
    }
    // Discourage opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * (1.0 - progress) + 0.3 * fitting_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 buckets
    // Leftovers in "awkward" classes (1..9 mod 10) are harder to refill than
    // multiples of 10; penalize dead space that is not a clean multiple.
    let pr = post_residual;
    let harm = pr % 10;
    if pr > 0 {
        match harm {
            0 => score -= 12.0,                 // clean slot, very reusable
            5 => score -= 4.0,                  // half-slot, moderately reusable
            1 | 2 | 3 | 4 | 6 | 7 | 8 | 9 => {
                // dead-space penalty grows as leftover shrinks into sliver range
                let sliver = if pr < 10 { 14.0 } else { 7.0 };
                score += sliver;
            }
            _ => {}
        }
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the leftover class admit next_item_size?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= pr {
            // next item fits here: strong reward, scaled by how snug it is
            let snug = (pr - nxt) as f64;
            score -= 20.0 - 0.15 * snug;
            // harmonic check: does placing next leave another clean class?
            if (pr - nxt) % 10 == 0 { score -= 8.0; }
        } else {
            // next item cannot use this bin's leftover: penalize by overflow gap
            let gap = (nxt - pr) as f64;
            score += 0.5 * gap;
            // if gap falls in a small dead class, extra penalty
            if gap < 10.0 { score += 5.0; }
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: proportional to wasted capacity
        // if the item goes alone here (capacity - item_size dead space).
        score = cap - item_size as f64;
        // Late in the stream, opening new bins is fine (no future to plan for)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // If current open bins are nearly full on average, new bin is natural
        if mean_residual < 25.0 { score -= 10.0; }
        // If no open bin fits (fitting_bins_count counts only open bins),
        // the new-bin call is the only option: make it attractive.
        if fitting_bins_count == 0 { score -= 60.0; }
        // A large next item may deserve a fresh bin rather than fragmenting
        if next_item_size > 0 && next_item_size >= 60 && item_size <= 40 {
            score -= 5.0;
        }
    }

    // Mild global pressure: many open bins -> prefer filling existing ones
    score += 0.3 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (good fillers)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (given items are >= 1, but practically small gaps are waste)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap just below the next item: dead space for the lookahead.
        score += (next_item_size - post_residual) as f64 * 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin (residual == capacity) is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open
        // or late in the stream (fragmentation risk).
        score += open_bins_count as f64 * 6.0 + progress * 30.0;
    } else {
        // Mild reward for filling existing bins, scaled by congestion.
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (consolidation).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for filling larger gaps when item is large.
    if item_size >= 50 {
        score -= 5.0;
    }

    score
}

