pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but scale by fill ratio
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Aggressive 2-step lookahead: reward when next item matches post_residual
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            // Perfect chain: next item exactly fills this bin
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here; reward proportionally to how well it nests
            let nest_quality = 1.0 - ((post - next_f) / bin_capacity as f64);
            score -= 35.0 * nest_quality;
        } else {
            // Next item won't fit here; penalize leaving awkward gaps
            let gap = next_f - post;
            score += 0.15 * gap;
        }

        // Compare post_residual relative to mean residual: prefer bins whose
        // resulting residual sits near the mean (keeps residuals uniform)
        let dev = (post - mean_residual).abs();
        score += 0.08 * dev;

        // Chain potential: residual after hypothetical next placement
        if next_item_size <= post_residual {
            let second_residual = post - next_f;
            // Favor residuals that are small or in the "awkward zone" (40..60)
            if second_residual <= 10.0 {
                score -= 15.0;
            } else if second_residual >= 40.0 && second_residual <= 60.0 {
                score += 8.0;
            }
        }
    } else {
        // Last item: just minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when several bins already fit the item
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 45.0;
        }
        // A new bin is attractive only if item is large and no bin fits well
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mild preference to consolidate across many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space < 10 is worst.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 0.2 * slack;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't fit here anyway; mild penalty if we leave big gap.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins; encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be conservative (prefer new bins when fit is bad);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= progress * 10.0 * fill_ratio;

    // New-bin candidate adjustments: an empty bin is attractive early or when fit is poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * (1.0 - progress) * (1.0 - tightness);
        score += 15.0 * progress; // late in stream, avoid new bins
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: early stream tolerates slack less (prefer tight fits),
    // late stream prefers filling bins fully
    let progress_coupling = 2.0 * progress * (1.0 - progress);
    score -= progress_coupling * pr * 0.5;

    // Reward tight fits more strongly as stream progresses
    score -= progress * (cap - pr) * 0.3;

    // Penalize dead space relative to mean residual across open bins
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.4;
    } else {
        score -= (pr - mean_residual) * 0.2;
    }

    // Lookahead: if next item fits into post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (pr - nxt) * 0.6 + 3.0;
        } else {
            // next item won't fit here: mild penalty for leaving awkward slack
            score += (nxt - pr) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: discourage opening a new bin unless existing bins are poor fits
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 4.0; // fresh bin has full room for lookahead
        }
    }

    // Mild penalty for many open bins (consolidation pressure)
    score += open_bins_count as f64 * 0.05;

    score
}
